using System.Collections.Generic;using UnityEngine;
// Independent new-skill projectile. Legacy AdventureProjectile is unchanged.
public sealed class SkillPiercingProjectile:MonoBehaviour {
 ThirdPersonHero hero;WeaponSkillExpansion observer;GearItem source;string skill;long attack;Vector3 direction;float damage,life=2.5f;Material material;readonly HashSet<Component> visited=new HashSet<Component>();
 public static void Spawn(ThirdPersonHero hero,WeaponSkillExpansion observer,string skill,long attack,GearItem source,RangedAimSolution aim,float damage){var g=new GameObject("蓄势贯矢真实弹体");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(g,hero.gameObject.scene);var v=g.AddComponent<SkillPiercingProjectile>();v.hero=hero;v.observer=observer;v.skill=skill;v.attack=attack;v.source=source.Clone();v.direction=aim.direction;v.damage=damage;g.transform.position=aim.origin;var line=g.AddComponent<LineRenderer>();v.material=new Material(Shader.Find("Universal Render Pipeline/Unlit")){color=new Color(.55f,.9f,1)};line.sharedMaterial=v.material;line.startWidth=.09f;line.endWidth=.035f;line.positionCount=2;line.SetPosition(0,aim.origin);line.SetPosition(1,aim.origin-aim.direction*.6f);observer?.Contact(skill,attack,"pierce-spawn",null,aim.origin,aim.direction,0,0);}
 void Update(){if(hero==null||hero.Health.Dead){Destroy(gameObject);return;}if(hero.GameplayPaused||Time.timeScale<=0)return;life-=Time.deltaTime;if(life<=0){Destroy(gameObject);return;}
  var overlaps=Physics.OverlapSphere(transform.position,CombatAim.ProjectileRadius,~0,QueryTriggerInteraction.Ignore);System.Array.Sort(overlaps,(a,b)=>Priority(a).CompareTo(Priority(b)));
  foreach(var c in overlaps){if(!CombatAim.Legal(c,hero))continue;if(!Contact(c,CombatAim.OverlapPoint(c,transform.position)))return;}
  float distance=23*Time.deltaTime;var hits=Physics.SphereCastAll(transform.position,CombatAim.ProjectileRadius,direction,distance,~0,QueryTriggerInteraction.Ignore);System.Array.Sort(hits,(a,b)=>a.distance==b.distance?Priority(a.collider).CompareTo(Priority(b.collider)):a.distance.CompareTo(b.distance));
  foreach(var hit in hits){if(!CombatAim.Legal(hit.collider,hero))continue;if(!Contact(hit.collider,hit.point))return;}
  Vector3 before=transform.position;transform.position+=direction*distance;var line=GetComponent<LineRenderer>();line.SetPosition(0,transform.position);line.SetPosition(1,transform.position-direction*.6f);observer?.Contact(skill,attack,"pierce-flight",null,before,direction,0,0);
 }
 static int Priority(Collider c)=>c.GetComponentInParent<CombatEnemy>()==null&&c.GetComponentInParent<AdventureResource>()==null?0:1;
 bool Contact(Collider c,Vector3 p){var enemy=c.GetComponentInParent<CombatEnemy>();var node=c.GetComponentInParent<AdventureResource>();Component target=enemy!=null?(Component)enemy:node;if(target==null){observer?.Contact(skill,attack,"pierce-blocked",c,p,direction,0,0);Destroy(gameObject);return false;}if(visited.Contains(target))return true;visited.Add(target);float before=enemy!=null?enemy.Health.Current:node.Health;if(enemy!=null)WeaponHit.Apply(hero,enemy,damage,p,direction,source,true);else node.Hit(damage,hero);float after=enemy!=null?enemy.Health.Current:node.Health;observer?.Contact(skill,attack,"pierce-contact",target,p,direction,before,after);AdventurePulse.SpawnImpact(p,0,new Color(.55f,.9f,1),gameObject.scene,hero);if(visited.Count>=3){Destroy(gameObject);return false;}return true;}
 public static void Clear(ThirdPersonHero hero){if(hero==null)return;foreach(var item in FindObjectsByType<SkillPiercingProjectile>())if(item.hero==hero){item.enabled=false;Destroy(item.gameObject);}}
 void OnDestroy(){if(material!=null)Destroy(material);}
}
public sealed class SkillImpactField:MonoBehaviour {
 ThirdPersonHero hero;WeaponSkillExpansion observer;GearItem source;string skill;long attack;float damage,radius,next;int pulses;
 public static void Spawn(ThirdPersonHero hero,WeaponSkillExpansion observer,string id,long attack,GearItem source,Vector3 point,float damage,float radius){var g=new GameObject("余烬符阵真实区域");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(g,hero.gameObject.scene);g.transform.position=point;var f=g.AddComponent<SkillImpactField>();f.hero=hero;f.observer=observer;f.skill=id;f.attack=attack;f.source=source.Clone();f.damage=damage;f.radius=radius;f.next=Time.time+.25f;}
 void Update(){if(hero==null||hero.Health.Dead){Destroy(gameObject);return;}if(hero.GameplayPaused||Time.timeScale<=0||Time.time<next)return;next=Time.time+.6f;var visited=new HashSet<Component>();Vector3 center=transform.position;AdventurePulse.SpawnImpact(center,radius,new Color(1,.4f,.12f),gameObject.scene,hero);CombatFeedback.Find(this)?.RangedRelease(hero,GearType.Staff);
  foreach(var c in Physics.OverlapSphere(center,radius,~0,QueryTriggerInteraction.Ignore)){if(!CombatAim.Legal(c,hero))continue;var enemy=c.GetComponentInParent<CombatEnemy>();var node=c.GetComponentInParent<AdventureResource>();Component target=enemy!=null?(Component)enemy:node;if(target==null||visited.Contains(target))continue;var point=CombatAim.OverlapPoint(c,center);if(!AdventureCombat.Sight(center,point,target)){observer?.Contact(skill,attack,"field-obstructed",target,point,Vector3.zero,0,0);continue;}visited.Add(target);float before=enemy!=null?enemy.Health.Current:node.Health;if(enemy!=null)WeaponHit.Apply(hero,enemy,damage,point,(point-center).normalized,source,true);else node.Hit(damage,hero);float after=enemy!=null?enemy.Health.Current:node.Health;observer?.Contact(skill,attack,"field-contact",target,point,Vector3.zero,before,after);}
  observer?.Contact(skill,attack,"field-pulse",null,center,Vector3.zero,0,0);if(++pulses>=3)Destroy(gameObject);
 }
 public static void Clear(ThirdPersonHero hero){if(hero==null)return;foreach(var item in FindObjectsByType<SkillImpactField>())if(item.hero==hero){item.enabled=false;Destroy(item.gameObject);}}
}
